const GITHUB_DIFF_LINE_HEIGHT: f32 = 24.0;
const GITHUB_DIFF_OVERSCAN: usize = 16;
const GITHUB_DIFF_CHROME_WIDTH: f32 = 122.0;
const GITHUB_DIFF_MIN_WRAP_COLUMNS: usize = 80;
