    #[test]
    fn harness_turn_completion_events_exclude_pi_maintenance() {
        assert!(agent_event_completes_turn(
            AgentState::Completed,
            Some("Stop")
        ));
        assert!(agent_event_completes_turn(
            AgentState::Completed,
            Some("agent_end")
        ));
        assert!(!agent_event_completes_turn(
            AgentState::Completed,
            Some("session_compact")
        ));
        assert!(!agent_event_completes_turn(
            AgentState::Completed,
            Some("auto_compaction_end")
        ));
        assert!(!agent_event_completes_turn(
            AgentState::Running,
            Some("agent_end")
        ));
    }

